import React, { useState } from 'react';

// Placeholder function to simulate fetching download links
// In a real app, this would make an API call to your backend
const fetchDownloadOptions = async (url) => {
  console.log('Fetching options for:', url);
  // Simulate network delay
  await new Promise(resolve => setTimeout(resolve, 1500));

  // Simulate success for a specific dummy URL
  if (url.includes('facebook.com/video/')) {
    // Simulate successful response with download options
    return [
      { quality: 'HD', url: '#', format: 'MP4', size: 'Approx. 50MB' },
      { quality: 'SD', url: '#', format: 'MP4', size: 'Approx. 20MB' },
    ];
  } else if (url === '') {
    throw new Error('Please enter a Facebook video URL.');
  }
  else {
    // Simulate an error
    throw new Error('Invalid URL or failed to fetch video. Please check the URL or try again.');
  }
};


function HomePage() {
  const [url, setUrl] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState(null);
  const [downloadOptions, setDownloadOptions] = useState([]); // Array<{quality, url, format, size}>

  const handleInputChange = (event) => {
    setUrl(event.target.value);
     // Clear error when user starts typing again
    if (error) {
        setError(null);
    }
     // Clear previous results when input changes
    if (downloadOptions.length > 0) {
        setDownloadOptions([]);
    }
  };

  const handleDownloadClick = async () => {
    setError(null); // Clear previous errors
    setDownloadOptions([]); // Clear previous results
    setIsLoading(true);

    try {
      const options = await fetchDownloadOptions(url);
      setDownloadOptions(options);
    } catch (err) {
      setError(err.message || 'An unexpected error occurred.');
      setDownloadOptions([]); // Ensure no stale options are shown
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-gray-100 flex flex-col items-center justify-center p-4">
      <div className="bg-white shadow-md rounded-lg p-6 md:p-8 w-full max-w-2xl">
        <h1 className="text-2xl md:text-3xl font-bold text-center text-gray-800 mb-6">
          Facebook Video Downloader
        </h1>

        <div className="space-y-4">
          {/* Input Field */}
          <div>
            <label htmlFor="videoUrl" className="block text-sm font-medium text-gray-700 mb-1">
              Paste Facebook Video URL here:
            </label>
            <input
              type="url"
              id="videoUrl"
              value={url}
              onChange={handleInputChange}
              placeholder="https://www.facebook.com/watch/?v=1234567890"
              className="w-full p-3 border border-gray-300 rounded-md focus:ring-2 focus:ring-blue-500 focus:border-transparent transition duration-150 ease-in-out"
              disabled={isLoading}
            />
          </div>

          {/* Download Button */}
          <button
            onClick={handleDownloadClick}
            disabled={isLoading || !url} // Disable if loading or URL is empty
            className="w-full bg-blue-600 hover:bg-blue-700 text-white font-bold py-3 px-4 rounded-md transition duration-150 ease-in-out disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center"
          >
            {isLoading ? (
              <>
                <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                  <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                  <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                </svg>
                Processing...
              </>
            ) : (
              'Download'
            )}
          </button>
        </div>

        {/* Error Display */}
        {error && (
          <div className="mt-4 p-3 bg-red-100 border border-red-400 text-red-700 rounded-md text-center">
            {error}
          </div>
        )}

        {/* Download Options Display */}
        {downloadOptions.length > 0 && (
          <div className="mt-6 border-t border-gray-200 pt-6">
            <h2 className="text-xl font-semibold text-gray-700 mb-4 text-center">Available Downloads:</h2>
            <div className="space-y-3">
              {downloadOptions.map((option, index) => (
                <a
                  key={index}
                  href={option.url} // In a real app, this URL would point to the actual video file
                  download // Suggests the browser should download the linked file
                  target="_blank" // Open in new tab, useful if direct download doesn't trigger
                  rel="noopener noreferrer"
                  className="block bg-green-500 hover:bg-green-600 text-white font-medium py-3 px-4 rounded-md text-center no-underline transition duration-150 ease-in-out"
                >
                  Download {option.format} - {option.quality} {option.size ? `(${option.size})` : ''}
                </a>
              ))}
            </div>
             <p className="text-xs text-gray-500 mt-4 text-center">
                Tip: Right-click the button and choose "Save link as..." if the download doesn't start automatically.
            </p>
          </div>
        )}

        {/* Basic How-To / Disclaimer */}
         {!isLoading && !error && downloadOptions.length === 0 && (
             <div className="mt-6 text-center text-gray-500 text-sm">
                <p>Enter the full URL of the Facebook video you want to download.</p>
                <p className="mt-2 text-xs">Please ensure you have the necessary permissions to download the video. Downloads are intended for personal offline use only.</p>
            </div>
         )}
      </div>

        {/* Footer for Policy Links (Optional) */}
        <footer className="text-center mt-8 text-gray-500 text-xs">
            <a href="/privacy-policy" className="hover:underline mx-2">Privacy Policy</a> |
            <a href="/terms-of-service" className="hover:underline mx-2">Terms of Service</a>
            <p className="mt-1">&copy; {new Date().getFullYear()} Your Site Name. All rights reserved.</p>
        </footer>
    </div>
  );
}

export default HomePage;
